/**
 * One model's licence, as its lane's catalog states it, with the text.
 *
 * `spdx`, `name` and `digest` are the catalog entry's `licence`; `digest` is
 * `sha256:` and the hex SHA-256 of `text` encoded as UTF-8. `installed` is the
 * entry's own.
 */
export type ModelLicenceResponse = {
  provider: Provider;
  transport: ProviderTransport;
  model: string;
  installed: boolean;
  spdx: string | null;
  name: string;
  digest: string;
  text: string;
};

/**
 * Canonical product identities shared by requests and configuration.
 */
export type Provider =
  | "claude"
  | "codex"
  | "antigravity"
  | "kimi"
  | "zai"
  | "zhipu"
  | "deepseek"
  | "moonshot"
  | "minimax"
  | "qwen"
  | "ollama"
  | "llamacpp";

/**
 * How a run reaches a named provider product.
 */
export type ProviderTransport = "api" | "cli";

/**
 * One file of a skill: its path within the skill, size and digest.
 */
export type SkillFileRecord = {
  /**
   * Relative to the skill's directory, '/'-separated.
   */
  path: string;
  /**
   * The file's size in UTF-8 bytes.
   */
  bytes: number;
  digest: string;
};

/**
 * Every skill of the package, ordered by name, and the set's revision.
 */
export type SkillListResponse = {
  revision: string;
  skills: SkillRecord[];
};

/**
 * One skill: what it is, when it applies, and the files it is made of.
 */
export type SkillRecord = {
  name: string;
  description: string;
  /**
   * The skill's parsed selection predicate, without the keys it leaves unset;
   * null when it declares none.
   */
  applies_when: { [key: string]: unknown } | null;
  digest: string;
  /**
   * Every file of the skill, SKILL.md included, in path order.
   */
  files: SkillFileRecord[];
};
